import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"ER 到关系","description":"","frontmatter":{"title":"ER 到关系","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/er-to-rel.md","filePath":"cs/er-to-rel.md","lastUpdated":1789023840000}'),p={name:"cs/er-to-rel.md"};function c(B,a,_,m,A,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="er-到关系" tabindex="-1">ER 到关系 <a class="header-anchor" href="#er-到关系" aria-label="Permalink to &quot;ER 到关系&quot;">​</a></h1><div class="epigraph"><p>实体与联系是设计草图；落到关系模型时，实体成表，联系成外键或单独的关系。</p><footer>—— 据 Chen, The Entity-Relationship Model, TODS 1976；Date 对从 ER 到表的整理</footer></div><p><a href="/cs/relational-model">上一课</a>把事实命名成属性上的元组集合。本课不重定义域与模式。缺口是设计入口：人们先画「谁与谁有关」，再写成表。Chen 的实体–联系图是草图；本课只收<strong>翻译规则</strong>，使后课键与完整性有来历。不写 SQL。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>关系模型禁止把指针当一等对象，但建模仍要从现实对象起步。实体有属性，联系有基数（一对多、多对多）。若不翻译，读者会以为表是从文件记录直接改名。缺口是：强实体 → 关系；多对多联系 → 带两端键的关系；一对多常把键放在多方。弱实体带上拥有者的键。</p><p><span class="marginnote">ER 不是存储。ISA 层次如何并成一张表或拆成多张，是后课范式的亲戚，本课只要求翻译后仍是关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个实体集一张表，属性成列。二元多对多：联系表，属性为两端候选键（后课才叫外键）。一对一按哪一侧可选来决定键放哪。三元联系不要强行拆成三个二元而不检查语义。本课不引入全部 Chen 记号变体。</p>',8)),(e(),n(h,null,{default:r(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E5%AE%9E%E4%BD%93%E9%9B%86%22%5D%20--%3E%20REL%5B%22%E5%85%B3%E7%B3%BB%22%5D%0A%20%20RELN%5B%22%E5%A4%9A%E5%AF%B9%E5%A4%9A%E8%81%94%E7%B3%BB%22%5D%20--%3E%20BRIDGE%5B%22%E8%81%94%E7%B3%BB%E5%85%B3%E7%B3%BB%22%5D%0A%20%20CARD%5B%22%E4%B8%80%E5%AF%B9%E5%A4%9A%22%5D%20--%3E%20FK%5B%22%E5%A4%9A%E6%96%B9%E6%8C%81%E6%9C%89%E4%B8%80%E7%AB%AF%E7%9A%84%E9%94%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>翻译保证：图画上的「一个订单属于一个客户」在值上可检查，而不是靠应用程序记住指针。后课<a href="/cs/keys-integrity">键与完整性</a>会把「一端的键」升级成候选键与外键约束。代数仍对翻译后的关系运算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 UML 类图当另一套数据模型插进主干，不讨论 ORM 的懒加载。元组如何唯一、引用如何禁止悬挂，下一课。</p><p>后课默认：表来自实体与联系的翻译。还没有主键声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ER 是草图；实体成表，多对多成联系表。</li><li>一对多把键放在多方。</li><li>键与参照完整性下一课。</li><li>出处：Chen, <em>TODS</em> 1976；Date；Codd 1970。</li></ul>',7))])}const D=l(p,[["render",c]]);export{T as __pageData,D as default};
